<?php if ($visits === []): ?><div class="patient-empty-state"><i class="bi bi-clipboard2-pulse" aria-hidden="true"></i><strong>No visits found</strong><span>Recorded consultations will appear here.</span></div><?php else: ?><div class="table-responsive patient-visits-table-wrap"><table class="table patient-visits-table"><caption class="sr-only">Patient visit history</caption><thead><tr><th>Visit</th><th>Doctor</th><th>Date / time</th><th>Service</th><th>Status / type</th><th>Records</th><th>Actions</th></tr></thead><tbody><?php foreach ($visits as $visit): ?><tr><td data-label="Visit"><strong class="patient-visit-value" title="<?= esc($visit['consultation_number'], 'attr') ?>"><?= esc($visit['consultation_number']) ?></strong><small class="d-block text-muted"><?= esc($visit['appointment_number'] ?: 'Appointment not linked') ?></small></td><td data-label="Doctor"><strong class="patient-visit-value">Dr. <?= esc(trim(($visit['doctor_first_name'] ?? '') . ' ' . ($visit['doctor_last_name'] ?? ''))) ?></strong><small class="d-block text-muted patient-visit-value" title="<?= esc($visit['specialization'], 'attr') ?>"><?= esc($visit['specialization'] ?: 'Not recorded') ?></small></td><td data-label="Date / time"><strong><?= esc($visit['visit_date_display']) ?></strong><small class="d-block text-muted"><?= esc($visit['visit_time_display']) ?></small></td><td data-label="Service"><span class="patient-visit-value" title="<?= esc($visit['service_display'], 'attr') ?>"><?= esc($visit['service_display']) ?></span></td><td data-label="Status / type"><span class="badge patient-status-badge patient-status-<?= esc($visit['status']) ?>"><?= esc($visit['status_label']) ?></span><small class="d-block text-muted"><?= esc($visit['type_label']) ?></small></td><td data-label="Records"><small><?= ! empty($visit['prescription_id']) ? 'Prescription available' : 'No prescription' ?></small><small class="d-block text-muted"><?= ! empty($visit['invoice_id']) ? 'Invoice available' : 'No invoice' ?></small></td><td data-label="Actions"><div class="dropdown"><button class="btn btn-sm btn-primary dropdown-toggle" type="button" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">More Actions</button><div class="dropdown-menu dropdown-menu-right"><button class="dropdown-item patient-visit-view" type="button" data-id="<?= (int) $visit['id'] ?>" data-toggle="modal" data-target="#patient-visit-detail-modal">View visit</button></div></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
